    vocab=[("diversidad", "que las personas somos distintas"), ("costumbre", "forma de hacer algo que se repite en un grupo"), ("creencia", "idea importante en la que una persona confía"), ("estereotipo", "creer que todas las personas de un grupo son iguales"), ("curiosidad", "ganas de saber y aprender")],
