    context=[ex("En el patio, una niña intenta alcanzar su balón que quedó en un techo alto. Un grupo quiere subir a buscarlo. ¿Qué es lo mejor que pueden hacer?", "Avisar a una persona adulta y no subir", "Subir es peligroso.")],
    selfcheck=[ex("¿Qué pregunta hago antes de ayudar?", "¿Quieres ayuda?", "Así pido el consentimiento."), ex("Si dicen que no a mi ayuda, ¿qué hago?", "Lo respeto", "Es su decisión."), ex("¿Cuándo debo avisar a un adulto de inmediato?", "Cuando alguien está en peligro", "Yo no puedo resolverlo solo.")],
